def transform(g):
    h,w=len(g),len(g[0])
    o=[row[:] for row in g]
    for c in range(w):
        if g[h-1][c]==0: continue
        for r in range(h-1,-1,-1):
            v=g[r][c]
            if v:
                r2=r-1
                while r2>=0 and g[r2][c]==0:
                    o[r2][c]=v; r2-=1
    return o
